import { useStore } from 'vuex'
import { computed } from 'vue'
import axios from 'axios'
import { API_CONFIG } from '@/config/config'
import { ElMessage } from 'element-plus'

export default function useLike() {
  const store = useStore()
  const currentUser = computed(() => store.state.user || {})

  const toggleLike = async (resourceType, resourceId) => {
    console.log(`尝试点赞${resourceType}，ID:`, resourceId)
    
    const urlMap = {
      moment: `${API_CONFIG.BASE_URL}/article/like_moment`,
      comment: `${API_CONFIG.BASE_URL}/article/like_comment`
    }

    try {
      // 直接调用API，不依赖本地数据
      const response = await axios.post(urlMap[resourceType], {
        [`${resourceType}_id`]: resourceId,
        user_id: currentUser.value.id,
        // 这里无法预先知道点赞状态，由服务器决定
      }, {
        headers: {
          Authorization: `Bearer ${store.state.token}`
        },
        timeout: 5000
      })

      if (response.data.success) {
        const isLiked = response.data.is_liked
        const likesCount = response.data.likes_count
        
        ElMessage.success(isLiked ? '点赞成功' : '已取消点赞')
        
        // 返回点赞结果
        return {
          isLiked,
          likes: likesCount
        }
      } else {
        throw new Error(response.data.msg || '操作失败')
      }
    } catch (error) {
      console.error('点赞操作失败:', error)
      ElMessage.error(`操作失败: ${error.response?.data?.msg || '网络错误'}`)
      return null
    }
  }

  // 新增：更新本地数据的辅助函数
  const updateLocalLikeStatus = (moments, resourceType, resourceId, isLiked, likesCount) => {
    if (resourceType === 'moment') {
      const moment = moments.find(m => m.id === resourceId || m.id.toString() === resourceId.toString())
      if (moment) {
        moment.isLiked = isLiked
        moment.stats = moment.stats || { likes: 0 }
        moment.stats.likes = likesCount
        
        // 更新like_users列表
        if (isLiked) {
          moment.like_users = [
            ...(moment.like_users || []),
            currentUser.value.id
          ]
        } else {
          moment.like_users = (moment.like_users || [])
            .filter(id => id !== currentUser.value.id)
        }
        
        return true
      }
    } else if (resourceType === 'comment') {
      for (const moment of moments) {
        if (!moment.comments) continue
        
        const comment = moment.comments.find(c => 
          c.id === resourceId || c.id.toString() === resourceId.toString()
        )
        
        if (comment) {
          comment.isLiked = isLiked
          comment.likes = likesCount
          return true
        }
      }
    }
    
    console.warn(`未找到本地${resourceType}资源更新点赞状态，ID:`, resourceId)
    return false
  }

  return {
    toggleLike,
    updateLocalLikeStatus
  }
}
